Gc unicode_gc_table(uint32_t cp) {
    size_t lo = 0;
    size_t hi = sizeof(ranges) / sizeof(ranges[0]);
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;
        const Range *r = &ranges[mid];
        if (cp < r->lo) hi = mid; else if (cp > r->hi) lo = mid + 1; else return r->gc;
    }
    return GC_OTHER;
}
